inputs = ['uk', 'gkh', 'igca', 'iddi', 'izcb']
outputs = ['uvgk', 'gvgkh', 'gwzgca', 'gwzddgwz', 'gwzzccyd']

# Let's examine each pair to see the differences
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Pair {i}: '{inp}' -> '{outp}'")

    # Find differing positions
    min_len = min(len(inp), len(outp))
    diff_positions = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            diff_positions.append((j, inp[j], outp[j]))

    # Check if we have length differences
    if len(inp) != len(outp):
        if len(inp) > len(outp):
            print(f"  Length decreased by {len(inp) - len(outp)}")
        else:
            print(f"  Length increased by {len(outp) - len(inp)}")

    if diff_positions:
        print(f"  Differences at positions: {diff_positions}")
    else:
        print("  No character differences found")
    print()

